def ema(values, length: int) -> float:
    """Exponential moving average of the last values. Returns the final EMA, or the
    simple mean if there's less than `length` data."""
    if not values:
        return 0.0
    k = 2.0 / (length + 1)
    e = values[0]
    for v in values[1:]:
        e = v * k + e * (1 - k)
    return e

